[dependencies]
# Experimental VR terrain PoC; pinned to a Bevy 0.19-compatible, internally consistent revision.
bevy_mod_openxr = { git = "https://github.com/awtterpip/bevy_oxr", rev = "4e2998531bd4f7d9cdce156148f9a5b7dd5cd260", features = ["window_support"], optional = true }
bevy_mod_xr = { git = "https://github.com/awtterpip/bevy_oxr", rev = "4e2998531bd4f7d9cdce156148f9a5b7dd5cd260", optional = true }
openxr = { version = "=0.21.1", optional = true }

crash_log::install();
#[cfg(feature = "vr")]
if vr::requested() { return vr::run(); }
#[cfg(not(feature = "vr"))]
if std::env::var("RC_VR").is_ok_and(|s| s == "1") {
    anyhow::bail!("RC_VR=1 requires a build with --features vr; refusing a silent desktop fallback");
}
